#define int long long
const int INF = 1e18;

int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, p;
    cin >> n >> k >> p;

    vector<int> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        int val;
        cin >> val;
        prefix[i + 1] = (prefix[i] + val);
    }

    vector<int> dp_prev(n + 1, INF);
    vector<int> dp_curr(n + 1, INF);
    dp_prev[0] = 0;

    for (int part = 1; part <= k; ++part) {
        fill(dp_curr.begin(), dp_curr.end(), INF);

        vector<int> best_C(p, INF);

        vector<int> p_min(p, INF), s_min(p, INF);

        for (int j = 1; j <= n; ++j) {
            int t = j - 1;
            if (dp_prev[t] < INF) {
                int mod_t = prefix[t] % p;
                int val = dp_prev[t] - mod_t;

                if (val < best_C[mod_t]) {
                    best_C[mod_t] = val;

                    p_min[mod_t] = min((mod_t > 0 ? p_min[mod_t-1] : INF), best_C[mod_t]);
                    for(int i = mod_t + 1; i < p; ++i) {
                        p_min[i] = min(p_min[i-1], best_C[i]);
                    }
                    s_min[mod_t] = min((mod_t < p-1 ? s_min[mod_t+1] : INF), best_C[mod_t]);
                    for(int i = mod_t - 1; i >= 0; --i) {
                        s_min[i] = min(s_min[i+1], best_C[i]);
                    }
                }
            }

            int mod_j = prefix[j] % p;

            int res1 = p_min[mod_j];
            int res2 = (mod_j + 1 < p) ? s_min[mod_j + 1] : INF;

            int min_val = INF;
            if (res1 < INF) min_val = min(min_val, res1);
            if (res2 < INF) min_val = min(min_val, res2 + p);

            if (min_val < INF) {
                dp_curr[j] = mod_j + min_val;
            }
        }
        dp_prev = dp_curr;
    }

    cout << dp_prev[n] << '\n';

    return 0;
}